<?php
class Auth {
 static function throttle(string $scope,string $identity):void {
  $id=hash('sha256',$scope.'|'.strtolower($identity).'|'.($_SERVER['REMOTE_ADDR']??'cli'));
  tx(function()use($id){q('INSERT IGNORE INTO rate_limits(id,attempts,expires_at) VALUES(?,0,DATE_ADD(NOW(),INTERVAL 15 MINUTE))',[$id]);$r=one('SELECT * FROM rate_limits WHERE id=? FOR UPDATE',[$id]);if(strtotime($r['expires_at'])<time())q('UPDATE rate_limits SET attempts=0,expires_at=DATE_ADD(NOW(),INTERVAL 15 MINUTE) WHERE id=?',[$id]);elseif($r['attempts']>=10)fail('Too many attempts. Try again in 15 minutes.',429);q('UPDATE rate_limits SET attempts=attempts+1 WHERE id=?',[$id]);});
 }
 static function login(array $d,bool $admin=false):array {
  if(!$admin)module('accounts'); self::throttle($admin?'staff':'login',$d['email']??'');$table=$admin?'staff_users':'customers';$u=one("SELECT * FROM $table WHERE email=?",[strtolower(trim($d['email']??''))]);
  if(!$u||!password_verify($d['password']??'',$u['password'])||($admin&&!$u['enabled']))fail('Email or password is incorrect.',401);
  session_regenerate_id(true);unset($_SESSION['csrf']);if($admin)$_SESSION['staff']=['id'=>$u['id']];else {$_SESSION['customer_id']=$u['id'];if(enabled('wishlist'))foreach($_SESSION['wishlist']??[] as $pid)q('INSERT IGNORE INTO wishlists(customer_id,product_id) VALUES(?,?)',[$u['id'],$pid]);unset($_SESSION['wishlist']);}return ['redirect'=>$admin?base('admin/'):url('account')];
 }
 static function register(array $d):array {module('accounts'); self::throttle('register',$d['email']??''); self::password($d['password']??'');if(!filter_var($d['email']??'',FILTER_VALIDATE_EMAIL)||strlen(trim($d['name']??''))<2)fail('Enter a valid name and email.');if(one('SELECT id FROM customers WHERE email=?',[$d['email']]))fail('This email is already registered.');q('INSERT INTO customers(name,email,phone,password) VALUES(?,?,?,?)',[trim($d['name']),strtolower(trim($d['email'])),$d['phone']??'',password_hash($d['password'],PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['customer_id']=(int)db()->lastInsertId();return ['redirect'=>url('account')];}
 static function password(string $s):void{if(strlen($s)<12||strlen($s)>200)fail('Use a password of 12–200 characters.');}
 static function resetRequest(array $d):array {module('accounts');self::throttle('reset',$d['email']??'');$u=one('SELECT * FROM customers WHERE email=?',[$d['email']??'']);if($u){$token=bin2hex(random_bytes(32));q('INSERT INTO password_resets(customer_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))',[$u['id'],hash('sha256',$token)]);$link=(str_starts_with(base(),'http')?'':setting('site_origin','http://localhost')).url('reset',['token'=>$token]);$body="Reset your password within 30 minutes: $link";if((config('mail')['mode']??'')==='private')file_put_contents(ROOT.'/storage/private/mail-'.bin2hex(random_bytes(8)).'.txt',$u['email']."\n".$body);else{$m=new PHPMailer\PHPMailer\PHPMailer(true);$c=config('mail');$m->isSMTP();$m->Host=$c['host'];$m->Port=$c['port'];$m->SMTPAuth=true;$m->Username=$c['username'];$m->Password=$c['password'];$m->SMTPSecure=PHPMailer\PHPMailer\PHPMailer::ENCRYPTION_STARTTLS;$m->setFrom($c['from']);$m->addAddress($u['email']);$m->Subject='Password reset';$m->Body=$body;$m->send();}}return ['message'=>'If the account exists, a reset message has been sent.'];}
 static function reset(array $d):array {self::password($d['password']??'');return tx(function()use($d){$r=one('SELECT * FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() FOR UPDATE',[hash('sha256',$d['token']??'')]);if(!$r)fail('The reset link is invalid or expired.');q('UPDATE customers SET password=? WHERE id=?',[password_hash($d['password'],PASSWORD_DEFAULT),$r['customer_id']]);q('UPDATE password_resets SET used_at=NOW() WHERE customer_id=?',[$r['customer_id']]);return ['redirect'=>url('login')];});}
}
